@font-face{font-family:Manrope;src:url('./assets/fonts/manrope-cyrillic.woff2') format('woff2');font-weight:400 800;font-display:swap;unicode-range:U+0301, U+0400-045F,U+0490-0491,U+2116}@font-face{font-family:Manrope;src:url('./assets/fonts/manrope-latin.woff2') format('woff2');font-weight:400 800;font-display:swap}@font-face{font-family:Russo;src:url('./assets/fonts/russo-cyrillic.woff2') format('woff2');font-display:swap;unicode-range:U+0301,U+0400-045F,U+0490-0491,U+2116}@font-face{font-family:Russo;src:url('./assets/fonts/russo-latin.woff2') format('woff2');font-display:swap}
:root{font-family:Manrope,Arial,sans-serif;color:#f6f1e7;background:#142326;font-synthesis:none;text-rendering:optimizeLegibility;--gold:#eab96f;--gold-bright:#ffd28a;--cream:#f6f1e7;--muted:#a6a99d;--glass:rgba(21,30,30,.78);--border:rgba(239,220,181,.18);--green:#9baa73}*{box-sizing:border-box}html,body,#app{margin:0;width:100%;height:100%;overflow:hidden}body{min-width:320px;user-select:none;-webkit-tap-highlight-color:transparent}button{font:inherit;color:inherit}#game-shell{position:relative;width:100%;height:100%;min-height:480px;overflow:hidden;background:#d9b477;isolation:isolate}#scene{position:absolute;inset:0;z-index:-1}#scene canvas{width:100%;height:100%;display:block;touch-action:none}.world-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(17,26,27,.56) 0%,rgba(17,26,27,.09) 20%,transparent 52%,rgba(16,25,24,.2) 76%,rgba(13,22,22,.58) 100%),linear-gradient(90deg,rgba(15,24,24,.38),transparent 25%,transparent 75%,rgba(15,24,24,.28));z-index:0}.topbar{position:absolute;top:0;left:0;right:0;height:80px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,244,218,.12);background:linear-gradient(180deg,rgba(18,27,28,.32),rgba(18,27,28,.04));z-index:2}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{width:39px;height:39px;border:1px solid rgba(242,196,126,.66);border-radius:50%;display:grid;place-items:center;color:#ffd98e;font-size:23px;background:rgba(234,185,111,.13);box-shadow:0 0 25px rgba(238,175,87,.15)}.brand-copy{display:grid;gap:1px}.brand-copy strong{font:18px Russo,sans-serif;letter-spacing:1.6px}.brand-copy strong span{color:var(--gold)}.brand-copy small{color:#c6c0b1;font-size:8px;letter-spacing:2px}.top-center{font-size:10px;font-weight:800;letter-spacing:1.4px;color:#ebe2d3;display:flex;gap:10px;align-items:center}.live-dot{height:6px;width:6px;background:#d8b576;border-radius:50%;box-shadow:0 0 9px #edc678}.top-divider{color:#7a7769}.zone-name{color:#c8b994}.top-right{display:flex;align-items:center;gap:17px}.weather{font-size:12px;font-weight:700;color:#e9dfcf}.weather-sun{font-size:21px;vertical-align:-2px;color:#edc77e;margin-right:4px}.icon-button,.avatar-button{width:36px;height:36px;border:1px solid var(--border);background:rgba(16,25,25,.45);border-radius:50%;cursor:pointer;color:#f2dfbd}.icon-button{font-size:17px}.avatar-button{background:#bd8853;border:2px solid #e6bd77;color:white;font:16px Russo,sans-serif}.hud-left{position:absolute;z-index:2;top:101px;left:34px;width:290px;display:flex;flex-direction:column;gap:10px}.glass-card{background:var(--glass);border:1px solid var(--border);backdrop-filter:blur(13px);box-shadow:0 12px 32px rgba(17,20,18,.14)}.player-card{min-height:77px;padding:11px 12px;display:flex;align-items:center;gap:10px;border-radius:4px}.player-portrait{position:relative;width:46px;height:46px;border-radius:4px;background:linear-gradient(145deg,#deaf71,#845d3c);display:grid;place-items:center;overflow:hidden;border:1px solid rgba(255,221,157,.35)}.portrait-sun{position:absolute;width:37px;height:37px;border:1px solid rgba(255,224,166,.55);border-radius:50%;top:-12px;right:-4px}.portrait-figure{z-index:1;width:25px;height:25px;display:grid;place-items:center;border-radius:50%;background:#dfc89f;color:#5a4130;font:15px Russo,sans-serif;box-shadow:0 10px 0 3px #4e5e4d}.online-ring{position:absolute;bottom:2px;right:2px;width:7px;height:7px;border-radius:50%;background:#b3ca82;border:1px solid #1d2925;z-index:2}.player-info{flex:1;min-width:0}.player-name{font-size:11px;font-weight:800;letter-spacing:.8px;display:flex;align-items:center;gap:6px}.rank-tag{font-size:7px;color:#dfbd82;border:1px solid rgba(224,188,126,.4);padding:2px 4px;letter-spacing:.6px}.level-line{display:flex;justify-content:space-between;margin:6px 0 4px;color:#c5c4b8;font-size:8px;letter-spacing:.4px}.level-line b{color:#f4d395}.xp-text{color:#aaa99d}.xp-track,.health-track,.quest-track{height:4px;background:rgba(224,221,203,.13);position:relative;overflow:hidden}.xp-track span{height:100%;width:0;display:block;background:linear-gradient(90deg,#d9aa67,#f5d38e);transition:width .3s}.level-badge{border-left:1px solid rgba(255,255,255,.13);padding-left:11px;text-align:center;color:#c8b99a;font-size:8px;letter-spacing:1px;line-height:1.6}.level-badge b{font:17px Russo,sans-serif;color:#f4d496}.health-card{border-radius:4px;padding:11px 12px}.meter-label{display:flex;justify-content:space-between;align-items:center;font-size:9px;font-weight:800;letter-spacing:.8px;margin-bottom:8px}.heart-icon{font-size:12px;color:#d97d69;font-style:normal;margin-right:5px}.meter-label>b{font:12px Russo,sans-serif;color:#f5eee1}.meter-label>b small{font:9px Manrope,sans-serif;color:#aaa99d}.health-track{height:5px;border-radius:6px;background:rgba(216,218,203,.12)}.health-track>span{display:block;width:100%;height:100%;background:linear-gradient(90deg,#b45e50,#e48a68);transition:width .3s}.health-track>i{position:absolute;top:0;bottom:0;left:25%;width:1px;background:rgba(17,23,21,.35)}.health-track>i:nth-of-type(2){left:50%}.health-track>i:nth-of-type(3){left:75%}.currency-card{height:52px;padding:8px 12px;display:flex;align-items:center;gap:10px;border-radius:4px;text-align:left;cursor:pointer;transition:border-color .2s,transform .2s}.currency-card:hover{border-color:rgba(255,211,137,.55);transform:translateY(-1px)}.coin-icon{font-size:18px;color:#edbf6f;text-shadow:0 0 10px rgba(239,188,103,.28)}.currency-label{display:grid;gap:1px;flex:1}.currency-label small{font-size:7px;letter-spacing:1.2px;color:#b1aea2}.currency-label b{font:14px Russo,sans-serif;letter-spacing:.4px}.currency-plus{color:#e5bd7d;font-size:23px;font-weight:300}.quest-card{margin-top:5px;padding:13px;border-radius:4px}.quest-heading{display:flex;align-items:center;gap:9px}.quest-icon{width:29px;height:29px;border:1px solid rgba(230,189,121,.34);display:grid;place-items:center;border-radius:3px;color:#e7bf7b;font-size:18px}.quest-heading>div{display:grid;gap:2px;flex:1}.quest-heading>div small{font-size:7px;letter-spacing:1.1px;color:#c3b9a2}.quest-heading>div b{font-size:11px}.quest-live{font-size:7px;letter-spacing:.7px;color:#b7c58d;border:1px solid rgba(183,197,141,.32);padding:4px 5px}.quest-card>p{font-size:9px;color:#d0cfc4;margin:12px 0 9px}.quest-progress-row{font-size:8px;color:#e8dfce;display:flex;justify-content:space-between;margin-bottom:5px}.quest-reward{color:#edc77f;font-weight:800}.quest-reward i{font-style:normal}.quest-track{height:4px}.quest-track span{display:block;width:0;height:100%;background:#d6ae6e;transition:width .25s}.quest-foot{border-top:1px solid rgba(255,255,255,.09);margin-top:11px;padding-top:9px;display:flex;justify-content:space-between;align-items:center}.quest-foot>span{font-size:7px;color:#aaa99a;letter-spacing:.6px}.quest-foot>b{font-size:8px;color:#e6c27e}.quest-foot small{font-size:7px;font-weight:600;color:#aaa99a}.hint-card{display:flex;gap:9px;align-items:center;margin:3px 0 0;padding:7px 8px;color:rgba(244,235,216,.7);font-size:9px;line-height:1.65;text-shadow:0 1px 5px #202722}.hint-star{font-size:18px;color:#edc27a}.hud-right{position:absolute;z-index:2;top:104px;right:35px;width:250px}.nearby-head{display:flex;align-items:center;gap:7px;padding:0 0 9px;border-bottom:1px solid rgba(255,241,219,.21);font-size:8px;letter-spacing:1px;font-weight:800;color:#efe7d8}.radar-icon{font-size:17px;color:#edc77f}.nearby-head>b{margin-left:auto;color:#c7c1b4;font-size:7px}.enemy-alert{position:relative;margin-top:8px;display:flex;align-items:center;gap:9px;padding:9px 10px;background:rgba(30,34,30,.58);border:1px solid rgba(233,160,119,.21);border-radius:3px;backdrop-filter:blur(6px)}.alert-mark{width:24px;height:24px;display:grid;place-items:center;border:1px solid rgba(214,126,97,.42);color:#e58c6d;border-radius:50%;font:13px Russo,sans-serif}.enemy-alert>div{display:grid;gap:3px;flex:1}.enemy-alert>div b{font-size:9px}.enemy-alert>div small{font-size:7px;letter-spacing:.7px;color:#b8b2a7}.enemy-alert>div small i{font-style:normal;color:#d3916e}.alert-pulse{width:6px;height:6px;border-radius:50%;background:#d78062;box-shadow:0 0 9px #e2785b}.location-label{position:absolute;z-index:2;bottom:102px;left:36px;display:flex;gap:10px;align-items:center;color:#fff4db;text-shadow:0 2px 8px #2b2c22}.location-line{width:2px;height:33px;background:#eab96f;box-shadow:0 0 10px #e9b86a}.location-label>div{display:grid;gap:2px}.location-label small{font-size:7px;letter-spacing:1.3px;color:#e3d6b8}.location-label b{font:15px Russo,sans-serif;letter-spacing:.7px}.location-coords{font-size:7px;letter-spacing:1px;color:#e4d6bb;margin:15px 0 0 8px}.bottom-hud{position:absolute;z-index:2;bottom:22px;left:34px;right:34px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.bottom-hud>*{pointer-events:auto}.controls-hint{display:flex;align-items:center;gap:4px;padding-bottom:7px}.keycap{min-width:21px;height:21px;border:1px solid rgba(242,232,210,.43);border-bottom-width:2px;background:rgba(22,28,26,.55);border-radius:3px;display:inline-grid;place-items:center;font-size:8px;font-weight:800;color:#f1e8d6}.keycap.wide{min-width:48px;font-size:7px}.hint-text{font-size:7px;letter-spacing:.8px;color:#eee5d3;margin:0 5px}.hint-separator{height:16px;border-left:1px solid rgba(255,255,255,.3);margin:0 5px}.quick-slots{display:flex;gap:7px;position:absolute;left:50%;transform:translateX(-50%);bottom:0}.quick-slot{width:54px;height:57px;position:relative;display:grid;place-items:center;align-content:center;gap:1px;border:1px solid rgba(235,220,187,.3);background:rgba(19,28,28,.73);border-radius:4px;cursor:pointer;backdrop-filter:blur(8px);transition:.2s}.quick-slot:hover,.quick-slot.active-slot{border-color:#d7ad6f;background:rgba(49,44,32,.78)}.slot-key{position:absolute;top:3px;left:5px;font-size:7px;color:#d4c6a9}.slot-icon{font-size:21px;line-height:23px;color:#eac67e}.quick-slot small{font-size:6px;letter-spacing:.6px;color:#c9c4b7}.sword-icon{transform:rotate(-25deg);font-size:25px}.sand-icon{color:#a7a48a}.slot-lock{position:absolute;font-size:7px;right:4px;top:3px}.attack-button{min-width:116px;height:49px;display:flex;align-items:center;gap:10px;padding:0 12px;border:1px solid rgba(247,207,135,.62);border-radius:4px;background:linear-gradient(110deg,rgba(192,134,74,.95),rgba(143,91,51,.93));box-shadow:0 5px 22px rgba(43,27,16,.22),inset 0 1px rgba(255,255,255,.2);cursor:pointer;transition:transform .15s,filter .15s}.attack-button:hover{filter:brightness(1.12);transform:translateY(-2px)}.attack-button:active{transform:scale(.97)}.attack-sword{font-size:21px;color:#fff0d3}.attack-button>span:nth-child(2){display:grid;gap:2px;text-align:left}.attack-button b{font:10px Russo,sans-serif;letter-spacing:.5px}.attack-button small{font-size:7px;color:#ecd5b4}.attack-button kbd{font-size:8px;color:#f4dfbf;margin-left:auto;border:1px solid rgba(255,255,255,.28);border-radius:2px;padding:3px 5px}.minimap{position:absolute;z-index:2;right:36px;bottom:96px;width:146px;height:155px;border:1px solid rgba(235,220,187,.27);background:rgba(20,29,29,.7);backdrop-filter:blur(7px);padding:7px;border-radius:3px}.map-top{height:19px;font-size:7px;letter-spacing:.9px;color:#e4dccb;display:flex;align-items:center;gap:5px}.map-top span{font-size:12px;color:#e5bc75}.map-world{position:relative;height:118px;overflow:hidden;background:radial-gradient(ellipse at 70% 5%,#8a9b79 0 10%,transparent 11%),linear-gradient(150deg,#798a70 0%,#8f9773 32%,#b4a073 56%,#ceb17d 76%,#75918b 77%,#63827a 100%);border:1px solid rgba(239,222,184,.16)}.map-world:before{content:'';position:absolute;width:70px;height:130px;right:-22px;top:-25px;border-left:1px dashed rgba(255,236,191,.5);transform:rotate(36deg)}.map-water{position:absolute;width:70px;height:55px;right:-17px;bottom:-18px;border-radius:50%;background:rgba(73,119,117,.56)}.map-path{position:abs